package cn.training.evaluation;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.mock.web.MockHttpSession;
import org.springframework.test.web.servlet.*;
import org.springframework.http.MediaType;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;

/** 图形码只从测试会话读取，生产接口不返回验证码答案。 */
@SpringBootTest(properties={"app.security.admin-password=integration-only-password","spring.datasource.url=jdbc:h2:mem:phone;MODE=MySQL;DB_CLOSE_DELAY=-1;DATABASE_TO_LOWER=TRUE","spring.datasource.driver-class-name=org.h2.Driver","spring.datasource.username=sa","spring.datasource.password="})
@AutoConfigureMockMvc
class PhoneIdentityIntegrationTest {
 @Test void rejectionCannotBeBypassedAndReviewCannotBeRepeated()throws Exception{MockHttpSession s=captcha();register(s,payload(s,"TEACHER","13900139030")).andExpect(status().isOk());long id=jdbc.queryForObject("SELECT id FROM app_user WHERE phone='13900139030'",Long.class);mvc.perform(post("/api/business/accounts/"+id+"/review").with(user("admin")).with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"result\":\"REJECTED\",\"reason\":\"身份不符\"}")).andExpect(status().isOk());mvc.perform(post("/api/business/accounts/"+id+"/review").with(user("admin")).with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"result\":\"APPROVED\",\"reason\":\"重复处理\"}")).andExpect(status().isBadRequest());Map<String,Object>d=new HashMap<>();d.put("phone","13900139030");d.put("display_name","测试人员");d.put("role","TEACHER");d.put("enabled",true);mvc.perform(put("/api/business/users/"+id).with(user("admin")).with(csrf()).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsBytes(d))).andExpect(status().isBadRequest());assertFalse(jdbc.queryForObject("SELECT enabled FROM app_user WHERE id=?",Boolean.class,id));}
 @Test void passwordResetAndUnlockRequireAdminAndReason()throws Exception{MockHttpSession s=captcha();register(s,payload(s,"STUDENT","13800138030")).andExpect(status().isOk());long id=jdbc.queryForObject("SELECT id FROM app_user WHERE phone='13800138030'",Long.class);jdbc.update("UPDATE app_user SET locked_until=?,login_failures=5 WHERE id=?",new java.sql.Timestamp(System.currentTimeMillis()+900000),id);String path="/api/business/accounts/"+id; mvc.perform(post(path+"/unlock").with(user("13800138030")).with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"reason\":\"自解锁\"}")).andExpect(status().isForbidden());mvc.perform(post(path+"/unlock").with(user("admin")).with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{}")).andExpect(status().isBadRequest());mvc.perform(post(path+"/unlock").with(user("admin")).with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"reason\":\"本人核验\"}")).andExpect(status().isOk());assertNull(jdbc.queryForObject("SELECT locked_until FROM app_user WHERE id=?",java.sql.Timestamp.class,id));mvc.perform(post(path+"/reset-password").with(user("admin")).with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"password\":\"replacement-phone-password\",\"reason\":\"忘记密码\"}")).andExpect(status().isOk());mvc.perform(post("/api/auth/login").with(csrf()).param("username","13800138030").param("password","phone-test-password")).andExpect(status().isUnauthorized());mvc.perform(post("/api/auth/login").with(csrf()).param("username","13800138030").param("password","replacement-phone-password")).andExpect(status().isOk());}
 @Test void concurrentRegistrationKeepsOneAccountAndProfile()throws Exception{
  MockHttpSession a=captcha(),b=captcha();Map<String,Object> one=payload(a,"STUDENT","13800138020"),two=payload(b,"STUDENT","13800138020");java.util.concurrent.ExecutorService pool=java.util.concurrent.Executors.newFixedThreadPool(2);try{java.util.concurrent.Future<Integer>x=pool.submit(()->register(a,one).andReturn().getResponse().getStatus()),y=pool.submit(()->register(b,two).andReturn().getResponse().getStatus());int first=x.get(),second=y.get();assertTrue(first==200||second==200);assertTrue(first==400||first==409||second==400||second==409);assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM app_user WHERE phone='13800138020'",Integer.class));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM student",Integer.class));}finally{pool.shutdownNow();}
 }
 @Test void validImportCreatesUniqueEnabledPhoneAccounts()throws Exception{byte[] bytes;try(org.apache.poi.xssf.usermodel.XSSFWorkbook book=new org.apache.poi.xssf.usermodel.XSSFWorkbook();java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream()){org.apache.poi.ss.usermodel.Sheet sheet=book.createSheet();sheet.createRow(0);String[][] rows={{"13800138021","学员","STUDENT","phone-test-password"},{"13900139021","教师","TEACHER","phone-test-password"}};for(int i=0;i<rows.length;i++){org.apache.poi.ss.usermodel.Row row=sheet.createRow(i+1);for(int j=0;j<4;j++)row.createCell(j).setCellValue(rows[i][j]);}book.write(out);bytes=out.toByteArray();}mvc.perform(multipart("/api/business/accounts/import").file(new org.springframework.mock.web.MockMultipartFile("file","accounts.xlsx","application/octet-stream",bytes)).with(user("admin")).with(csrf())).andExpect(status().isOk()).andExpect(jsonPath("$.data").value(2));assertEquals(2,jdbc.queryForObject("SELECT COUNT(*) FROM app_user WHERE phone IS NOT NULL AND enabled=TRUE",Integer.class));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM teacher",Integer.class));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM student",Integer.class));}
 @Autowired MockMvc mvc;@Autowired JdbcTemplate jdbc;@Autowired ObjectMapper json;
 @BeforeEach void reset(){jdbc.update("DELETE FROM app_user WHERE username<>'admin'");jdbc.update("DELETE FROM student");jdbc.update("DELETE FROM teacher");}
 MockHttpSession captcha()throws Exception{MvcResult result=mvc.perform(get("/api/auth/captcha")).andExpect(status().isOk()).andExpect(content().contentType("image/png")).andReturn();assertTrue(result.getResponse().getContentAsByteArray().length>100);return (MockHttpSession)result.getRequest().getSession(false);}
 Map<String,Object> payload(MockHttpSession session,String role,String phone){Map<String,Object>d=new HashMap<>();d.put("phone",phone);d.put("display_name","测试人员");d.put("password","phone-test-password");d.put("role",role);d.put("captcha",session.getAttribute("captchaCode"));return d;}
 ResultActions register(MockHttpSession session,Map<String,Object>d)throws Exception{return mvc.perform(post("/api/auth/register").session(session).with(csrf()).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsBytes(d)));}
 @Test void studentRegistersAndCanOnlyAccessOwnPortal()throws Exception{MockHttpSession s=captcha();register(s,payload(s,"STUDENT","13800138001")).andExpect(status().isOk());assertEquals("13800138001",jdbc.queryForObject("SELECT username FROM app_user WHERE role='STUDENT'",String.class));String hash=jdbc.queryForObject("SELECT password_hash FROM app_user WHERE role='STUDENT'",String.class);assertTrue(hash.startsWith("{bcrypt}"));mvc.perform(post("/api/auth/login").with(csrf()).param("username","13800138001").param("password","phone-test-password")).andExpect(status().isOk());mvc.perform(get("/api/business/classes").with(user("13800138001"))).andExpect(status().isForbidden());mvc.perform(get("/api/portal/courses").with(user("13800138001"))).andExpect(status().isOk());}
 @Test void teacherRegistrationRequiresApproval()throws Exception{MockHttpSession s=captcha();register(s,payload(s,"TEACHER","13900139001")).andExpect(status().isOk());assertFalse(jdbc.queryForObject("SELECT enabled FROM app_user WHERE role='TEACHER'",Boolean.class));assertEquals(3,jdbc.queryForObject("SELECT COUNT(*) FROM account_permission p JOIN app_user u ON u.id=p.user_id WHERE u.role='TEACHER'",Integer.class));mvc.perform(post("/api/auth/login").with(csrf()).param("username","13900139001").param("password","phone-test-password")).andExpect(status().isUnauthorized());long id=jdbc.queryForObject("SELECT id FROM app_user WHERE role='TEACHER'",Long.class);mvc.perform(post("/api/business/accounts/"+id+"/review").with(user("admin")).with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"result\":\"APPROVED\",\"reason\":\"线下核验通过\"}")).andExpect(status().isOk());mvc.perform(post("/api/auth/login").with(csrf()).param("username","13900139001").param("password","phone-test-password")).andExpect(status().isOk());}
 @Test void invalidAndDuplicatePhonesRollbackProfiles()throws Exception{MockHttpSession s=captcha();register(s,payload(s,"STUDENT","12345678901")).andExpect(status().isBadRequest());assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM student",Integer.class));s=captcha();register(s,payload(s,"STUDENT","13800138002")).andExpect(status().isOk());s=captcha();register(s,payload(s,"TEACHER","13800138002")).andExpect(status().isBadRequest());assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM teacher",Integer.class));}
 @Test void captchaIsOneTimeAndExpires()throws Exception{MockHttpSession s=captcha();Map<String,Object>d=payload(s,"STUDENT","13800138003");d.put("captcha","wrong");register(s,d).andExpect(status().isBadRequest());assertNull(s.getAttribute("captchaCode"));s=captcha();d=payload(s,"STUDENT","13800138003");s.setAttribute("captchaAt",System.currentTimeMillis()-301000);register(s,d).andExpect(status().isBadRequest());}
 @Test void registrationCannotAssignAdminOrBindAnotherProfile()throws Exception{MockHttpSession s=captcha();register(s,payload(s,"ADMIN","13800138004")).andExpect(status().isBadRequest());s=captcha();Map<String,Object>d=payload(s,"STUDENT","13800138004");d.put("student_id",999);register(s,d).andExpect(status().isOk());assertNotEquals(999,jdbc.queryForObject("SELECT student_id FROM app_user WHERE phone='13800138004'",Long.class).longValue());}
 @Test void accountImportValidatesWholeFile()throws Exception{byte[] bytes;try(org.apache.poi.xssf.usermodel.XSSFWorkbook book=new org.apache.poi.xssf.usermodel.XSSFWorkbook();java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream()){org.apache.poi.ss.usermodel.Sheet sheet=book.createSheet();sheet.createRow(0);String[][] rows={{"13800138005","学员","STUDENT","phone-test-password"},{"invalid","教师","TEACHER","phone-test-password"}};for(int i=0;i<rows.length;i++){org.apache.poi.ss.usermodel.Row row=sheet.createRow(i+1);for(int j=0;j<4;j++)row.createCell(j).setCellValue(rows[i][j]);}book.write(out);bytes=out.toByteArray();}mvc.perform(multipart("/api/business/accounts/import").file(new org.springframework.mock.web.MockMultipartFile("file","accounts.xlsx","application/octet-stream",bytes)).with(user("admin")).with(csrf())).andExpect(status().isBadRequest());assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM app_user",Integer.class));}
}
